// Banco de Dados de Logos de Mercados e Marcas (Base64 / Rasterizado)
// Armazena em cache e banco local para carregamento instantâneo offline e PWA
const BANCO_LOGOS = {
  'atacadao': 'data:image/png;base64,',
  'assai': 'data:image/png;base64,',
  'diaadia': 'data:image/png;base64,',
  'dona': 'data:image/png;base64,',
  'carrefour': 'data:image/png;base64,',
  'bigbox': 'data:image/png;base64,',
  'paodeacucar': 'data:image/png;base64,'
};

// Função para recuperar logo por identificador ou nome
function obterLogoMercado(chave) {
  if (!chave) return null;
  const k = chave.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (BANCO_LOGOS[k]) return BANCO_LOGOS[k];
  for (let bKey in BANCO_LOGOS) {
    if (k.includes(bKey) || bKey.includes(k)) return BANCO_LOGOS[bKey];
  }
  return `logos/${k}.png`;
}
